参数解析示例：
```c
int opt;
while ((opt = getopt(argc, argv, "p:r:i:")) != -1) {
    switch (opt) {
    case 'p':
        config->port = atoi(optarg);
        break;
    case 'r':
        strncpy(config->root, optarg, sizeof(config->root) - 1);
        break;
    case 'i':
        strncpy(config->index, optarg, sizeof(config->index) - 1);
        break;
    default:
        return -1;
    }
}
```

